export function decodePartAt(data, depth, limit) {
  const r = new Reader(data);
  if (depth < 0 || limit < 1) throw r.refuse("depth_exceeded");
  r.depth = depth;
  r.limit = Math.min(limit, DEPTH_LIMIT);
  r.ws();
  const v = readPart(r);
  return [v, r.pos];
}

export function encodePartAt(v, depth) {
  if (depth < 0 || depth >= DEPTH_LIMIT) throw new Refusal("depth_exceeded", 0);
  checkPart(v, depth, DEPTH_LIMIT);
  const out = new Out();
  writePart(out, v, depth);
  const bytes = out.bytes();
  decodePartAt(bytes, depth, DEPTH_LIMIT);
  return bytes;
}

export function encodePart(v) {
  const bytes = encodePartAt(v, 0);
  const out = new Uint8Array(bytes.length + 1);
  out.set(bytes);
  out[bytes.length] = 0x0a;
  return out;
}

export function decodePart(data) {
  const [v, n] = decodePartAt(data, 0, DEPTH_LIMIT);
  const r = new Reader(data);
  r.pos = n;
  r.ws();
  if (r.pos !== r.buf.length) throw r.refuse("trailing_bytes");
  return v;
}

